<script lang="ts">
	import OperatorGuard from '$lib/components/OperatorGuard.svelte'; import PlatformNav from '$lib/components/PlatformNav.svelte'; import StatusBadge from '$lib/components/StatusBadge.svelte'; import { formatInstant } from '$lib/format'; import { request } from '$lib/session.svelte';
	let users=$state<any[]>([]),query=$state(''),error=$state(''),loading=$state(true);const filtered=$derived(users.filter((user)=>!query.trim()||`${user.email} ${user.display_name??''}`.toLowerCase().includes(query.trim().toLowerCase())));$effect(()=>{void load()});async function load(){try{users=await request<any[]>('/v1/platform/users');error=''}catch(cause){error=cause instanceof Error?cause.message:String(cause)}finally{loading=false}}
</script>
<svelte:head><title>Platform accounts · MakersBrain</title></svelte:head>
<OperatorGuard><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>Accounts</h1><p class="muted">People known to the control plane and whether their verified identity is linked.</p></div><button class="secondary" onclick={load}>Refresh</button></header><PlatformNav />{#if error}<p class="error">{error}</p>{/if}<label class="card search">Search accounts<input type="search" bind:value={query} placeholder="Name or email" /></label><section class="section card table-wrap">{#if loading}<div class="empty">Loading accounts…</div>{:else if filtered.length===0}<div class="empty">No accounts match.</div>{:else}<table><thead><tr><th>Person</th><th>Identity</th><th>Workshops</th><th>Locale</th><th>Created</th></tr></thead><tbody>{#each filtered as user (user.id)}<tr><td><strong>{user.display_name??user.email}</strong><div class="muted">{user.email}</div></td><td>{#if user.disabled_at}<StatusBadge state="disabled" />{:else if user.identity_linked}<StatusBadge state="ready" label="Linked" />{:else}<StatusBadge state="pending" label="Not linked" />{/if}</td><td>{user.workshop_count}</td><td>{user.locale.toUpperCase()}</td><td>{formatInstant(user.created_at)}</td></tr>{/each}</tbody></table>{/if}</section></OperatorGuard>
<style>.search{max-width:34rem}</style>
